#ifndef LOOPI4_GENERIC_H
#define LOOPI4_GENERIC_H

#include <complex>

extern "C" {
  extern std::complex<double> qli4(double const& p1, double const& p2, double const& p3, double const& p4, double const& s12, double const& s23, double const& m1, double const& m2, double const& m3, double const& m4, double const& mu2, int const& ep);
  extern std::complex<double> qli4c(double const& p1, double const& p2, double const& p3, double const& p4, double const& s12, double const& s23, std::complex<double> const& m1, std::complex<double> const& m2, std::complex<double> const& m3, std::complex<double> const& m4, double const& mu2, int const& ep);
}

extern std::complex<double> loopI4(double p1, double p2, double p3, double p4, double s12, double s23, double m1, double m2, double m3, double m4, double mu2, int ep);
extern std::complex<double> loopI4(double p1, double p2, double p3, double p4, double s12, double s23, std::complex<double> m1, std::complex<double> m2, std::complex<double> m3, std::complex<double> m4, double mu2, int ep);

#endif

#include <loopI4_generic.hpp>
#include <cmath>
#include <complex>
#include <iostream>
#include <scalarselect_mod.hpp>

using namespace scalarselect_mod;

std::complex<double> loopI4(double p1, double p2, double p3, double p4, double s12, double s23, double m1, double m2, double m3, double m4, double mu2, int ep) {

  std::complex<double> loopI4_res, resQCDLoop, resOneLOop;
  std::complex<double> result[3];

  if (scalarselect == 1 || scalarselect == 3) {
    resQCDLoop = qli4(p1, p2, p3, p4, s12, s23, m1, m2, m3, m4, mu2, ep);
  }

  if (scalarselect == 1) {
    // @coverage-probe
    loopI4_res = resQCDLoop;
    return loopI4_res;
  }

  if (scalarselect == 3) {
    if (std::abs(resOneLOop) > 1e-9 && std::abs(resQCDLoop / resOneLOop - 1.0) > 1e-9) {
      std::cout << "loopI4: " << p1 << ", " << p2 << ", " << p3 << ", " << p4 << ", " << s12 << ", " << s23 << ", " << m1 << ", " << m2 << ", " << m3 << ", " << m4 << ", " << mu2 << ", " << ep << std::endl;
      std::cout << "QCDLoop: " << resQCDLoop << std::endl;
      std::cout << "OneLOop: " << resOneLOop << std::endl;
      std::cout << "->ratio: " << resQCDLoop / resOneLOop << std::endl;
    }
  }

  return loopI4_res;
}

std::complex<double> loopI4(double p1, double p2, double p3, double p4, double s12, double s23, std::complex<double> m1, std::complex<double> m2, std::complex<double> m3, std::complex<double> m4, double mu2, int ep) {

  std::complex<double> loopI4_res, resQCDLoop, resOneLOop;
  std::complex<double> result[3];

  if (scalarselect == 1 || scalarselect == 3) {
    resQCDLoop = qli4c(p1, p2, p3, p4, s12, s23, m1, m2, m3, m4, mu2, ep);
  }

  if (scalarselect == 1) {
    loopI4_res = resQCDLoop;
    return loopI4_res;
  }

  if (scalarselect == 3) {
    if (std::abs(resOneLOop) > 1e-12 && std::abs(resQCDLoop / resOneLOop - 1.0) > 1e-12) {
      std::cout << "loopI4: " << p1 << ", " << p2 << ", " << p3 << ", " << p4 << ", " << s12 << ", " << s23 << ", " << m1 << ", " << m2 << ", " << m3 << ", " << m4 << ", " << mu2 << ", " << ep << std::endl;
      std::cout << "QCDLoop: " << resQCDLoop << std::endl;
      std::cout << "OneLOop: " << resOneLOop << std::endl;
      std::cout << "->ratio: " << resQCDLoop / resOneLOop << std::endl;
    }
  }

  return loopI4_res;
}

extern "C" {
  std::complex<double> loopI4_wrapper(double p1, double p2, double p3, double p4, double s12, double s23, double m1, double m2, double m3, double m4, double mu2, int ep) {
    return loopI4(p1, p2, p3, p4, s12, s23, m1, m2, m3, m4, mu2, ep);
  }

  std::complex<double> loopI4c_wrapper(double p1, double p2, double p3, double p4, double s12, double s23, std::complex<double> m1, std::complex<double> m2, std::complex<double> m3, std::complex<double> m4, double mu2, int ep) {
    return loopI4(p1, p2, p3, p4, s12, s23, m1, m2, m3, m4, mu2, ep);
  }
}

